function fold(value: string): string {
  return value.normalize('NFD').replace(/\p{M}/gu, '').toLowerCase();
}

function searchNeedles(needle: string): string[] {
  const needles = [needle];
  if (needle.endsWith('y') && needle.length > 3) needles.push(`${needle.slice(0, -1)}ies`);
  return needles;
}

function textMatches(haystack: string, needle: string): boolean {
  const folded = fold(haystack);
  if (searchNeedles(needle).some((item) => folded.includes(item))) return true;
  if (needle.length < 4) return false;
  return folded.split(/[^a-z0-9]+/).some((word) => word.startsWith(needle));
}

export function curatedWatchlistById(id: string): CuratedWatchlist | null {
  return CURATED_WATCHLISTS.find((list) => list.id === id) ?? null;
}

/** Match a list by its name, description, or any movie and show inside it. */
export function searchCuratedWatchlists(
  query: string,
  lists: readonly CuratedWatchlist[] = CURATED_WATCHLISTS,
): CuratedWatchlistMatch[] {
  const needle = fold(query.trim());
  if (!needle) return lists.map((list) => ({ list, matchedTitles: [] }));
  const matches: CuratedWatchlistMatch[] = [];
  for (const list of lists) {
    const matchedTitles = list.titles
      .filter((title) => textMatches(title.title, needle))
      .map((title) => title.title);
    const inList = textMatches(list.name, needle) || textMatches(list.blurb, needle);
    if (inList || matchedTitles.length > 0) matches.push({ list, matchedTitles });
  }
  return matches;
}

export function curatedWatchlistsForAudience(
  allowed: WatchlistAudience,
  lists: readonly CuratedWatchlist[] = CURATED_WATCHLISTS,
): readonly CuratedWatchlist[] {
  return lists.filter((list) => canViewAudience(allowed, list.audience));
}
